namespace GeetaStudio.Api;

public static class MediaPage
{
    public const string Html = """
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Character media library</title>
<style>body{font:1rem system-ui;color:#243e35;max-width:72rem;margin:2rem auto;padding:1rem}input,select,textarea,button{font:inherit;padding:.6rem;max-width:100%;box-sizing:border-box;min-height:44px}label{display:block;margin:.8rem 0}section,article{border:1px solid #9aafa1;padding:1rem;margin:1rem 0}img{max-width:100%;height:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere}:focus-visible{outline:3px solid #ad5d10}textarea{width:100%}button{margin:.3rem}small{display:block}</style>
<h1>Character media library</h1><p>Keep each character's pictures and voice together with permission, accessibility notes and review history. A local preview does not approve public use.</p>
<p><a href="/staff/characters">Create or update a character</a> · <a href="/staff/editorial">Editorial review</a> · <a href="/staff/watch">WATCH episodes</a> · <a href="/staff/trends">Trend stories</a></p>
<label>Workspace code <input id="tenant"></label><label>Universe code <input id="universe"></label><button id="load">Open library</button><p role="status" id="status"></p>
<section><h2>Available narration voices</h2><p>en-IN is the temporary technical default. Use an exact supported voice and language. Installed voices are local previews, not permission to redistribute; artwork, voice rights and human listening review remain pending. Tone fixtures are not narration.</p><button id="speechInventory">Inspect available voices</button><pre id="speechResources"></pre></section>
<section><h2>Add a picture or recording</h2><p>Plain PNG pictures and short PCM WAV recordings, up to1MiB. Active files and unsupported formats are rejected.</p>
<label>File <input type="file" accept=".png,.wav" id="file"></label><label>Asset name <input id="key"></label><label>Version <input id="version" type="number" min="1" value="1"></label><label>Description for people who cannot see or hear it <textarea id="description"></textarea></label>
<label>Use <select id="kind"><option>CharacterSheet</option><option>Pose</option><option>Scene</option><option>Voice</option><option>Music</option><option>Other</option></select></label>
<label>Character profile <select id="character"></select></label><label>Audience code <input id="audience"></label><label>Language <input id="locale" value="en-IN"></label>
<label>Permission <select id="license"><option value="Fixture">Controlled fixture — public release blocked</option><option value="OwnedOriginal">My original material — documented permission required</option><option value="Licensed">Licensed source — reviewed source records required</option><option value="PublicDomain">Public domain — reviewed source records required</option></select></label>
<label>Permission evidence reference <input id="permission" value="fixture:local-media-not-public"></label><label>Attribution <input id="attribution" value="Controlled local sample; human review pending"></label><label>Reviewed source snapshot codes, comma separated <input id="sources"></label><button id="upload">Add for review</button></section>
<section><h2>Review notes</h2><label>Review type <select id="mode"><option>Fixture</option><option>Manual</option></select></label><label>Review evidence reference <input id="review" value="fixture:local-quality-review-not-release"></label><label>Unresolved differences in appearance, voice or pronunciation, one per line <textarea id="deviations"></textarea></label><p>Approval requires an explicit review and no unresolved differences. A different provider or presentation gets a new package and fresh quality review.</p></section>
<section><h2>Pictures and recordings</h2><div id="assets"></div></section>
<section><h2>Create a character package</h2><p>Select the character above. Use reviewed pictures and recordings; each changed presentation needs a fresh review before binding.</p>
<label>Package name <input id="packageKey"></label><label>Package version <input id="packageVersion" type="number" min="1" value="1"></label><label>Presentation style <input id="packageStyle" value="Original fictional teacher"></label>
<label>Reviewed reference picture <select id="packageVisual"></select></label><label>Reviewed voice <select id="packageVoice"></select></label>
<label>Palette colours, comma separated <input id="palette" value="#245441,#F8F8F5"></label><label>Style rules, one per line <textarea id="styleRules">Preserve approved identity anchors; original fiction</textarea></label>
<label>Poses, comma separated <input id="poses" value="Front,Side"></label><label>Scene references, comma separated <input id="scenes" value="Community classroom"></label>
<label>Pronunciation substitutions, one word=spoken form per line <textarea id="pronunciation"></textarea></label><button id="createPackage">Create package for review</button></section>
<section><h2>Character packages</h2><div id="packages"></div></section>
<section><h2>Generation and recovery</h2><pre id="generations"></pre><pre id="profiles"></pre></section>
<details><summary>Package and provider administration</summary><p>Use the versioned owned request schema in MediaContracts. New guests use the same package flow. Voice IDs remain bound to their original provider. Paid/live providers are not qualified by these fixtures.</p>
<label>Operation <select id="operation"><option>packages</option><option>profiles</option><option>generations</option><option>reconcile</option><option>move</option></select></label><label>Request <textarea id="request" spellcheck="false">{}</textarea></label><button id="submit">Submit administration request</button><pre id="result"></pre></details>
<script>
const get=id=>document.getElementById(id),scope=()=>'/tenants/'+encodeURIComponent(get('tenant').value)+'/universes/'+encodeURIComponent(get('universe').value),base=()=>'/api/v1/media'+scope();
let versions=[],characters=[],runs=[];
async function call(path,data){const r=await fetch(path,{method:data?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:data?{'Content-Type':'application/json','X-ContentOS-Staff':'1'}:{},body:data?JSON.stringify(data):undefined});if(!r.ok)throw Error('Request denied or unavailable ('+r.status+'): '+await r.text());return r.status===204?null:await r.json();}
function text(tag,value,parent){const el=document.createElement(tag);el.textContent=value;parent.append(el);return el;}
function button(label,parent,fn){const b=text('button',label,parent);b.onclick=async()=>{try{await fn();await load();}catch(e){get('status').textContent=e.message;}};}
function review(row,decision){return {operationId:crypto.randomUUID(),expectedRowVersion:row.rowVersion,decision,mode:get('mode').value,evidenceReference:get('review').value,deviations:get('deviations').value.split('\n').filter(x=>x.trim())};}
async function load(){try{const assets=await call(base()+'/assets');versions=assets.flatMap(x=>x.versions);get('assets').replaceChildren();for(const asset of assets)for(const v of asset.versions){const a=document.createElement('article');get('assets').append(a);text('h3',asset.key+' · version '+v.version,a);text('p',v.accessibilityDescription,a);text('small',v.reviewStatus+' · '+v.info.mime+' · '+v.license.kind+' · '+v.license.attribution,a);if(v.blocks.length){text('p',v.blocks.join('; '),a);continue;}const media=document.createElement(v.info.mime==='image/png'?'img':'audio');media.src=base()+'/versions/'+v.id+'/preview';if(media.tagName==='IMG')media.alt=v.accessibilityDescription;else media.controls=true;a.append(media);button('Approve',a,()=>call(base()+'/versions/'+v.id+'/review',review(v,'Approve')));button('Reject',a,()=>call(base()+'/versions/'+v.id+'/review',review(v,'Reject')));button('Withdraw',a,()=>call(base()+'/versions/'+v.id+'/review',review(v,'Withdraw')));}
const packages=await call(base()+'/packages');get('packages').replaceChildren();for(const p of packages){const a=document.createElement('article');get('packages').append(a);text('h3',p.key+' · version '+p.version,a);text('p',p.rules.presentationStyle+' · '+p.rules.locale+' · '+p.reviewStatus,a);text('p',p.rules.styleRules.join('; ')+' · Poses: '+p.rules.poses.join(', '),a);text('p',p.blocks.join('; '),a);button('Approve package',a,()=>call(base()+'/packages/'+p.id+'/review',review(p,'Approve')));button('Withdraw package',a,()=>call(base()+'/packages/'+p.id+'/review',review(p,'Withdraw')));button('Bind reviewed package to character',a,()=>call(base()+'/packages/'+p.id+'/bind',{operationId:crypto.randomUUID()}));}
runs=await call(base()+'/generations');get('generations').textContent=JSON.stringify(runs,null,2);get('profiles').textContent=JSON.stringify(await call(base()+'/profiles'),null,2);
characters=await call('/api/v1/registry'+scope()+'/characters');get('character').replaceChildren();for(const c of characters){const o=document.createElement('option');o.value=c.profile.id;o.textContent=c.profile.rules.name+' · '+c.status;get('character').append(o);}refreshChoices();get('status').textContent='Current media and permissions loaded.';}catch(e){get('status').textContent=e.message;}}
function refreshChoices(){for(const name of ['packageVisual','packageVoice']){get(name).replaceChildren();for(const v of versions.filter(x=>x.reviewStatus==='Approved'&&x.blocks.length===0&&x.characterProfileRevisionId===get('character').value&&(name==='packageVisual'?x.info.mime==='image/png':x.info.mime==='audio/wav'))){const o=document.createElement('option');o.value=v.id;o.textContent=v.kind+' · '+v.accessibilityDescription;get(name).append(o);}}}
get('character').onchange=refreshChoices;
get('createPackage').onclick=async()=>{try{const character=characters.find(x=>x.profile.id===get('character').value),voice=versions.find(x=>x.id===get('packageVoice').value);if(!character||!voice||!get('packageVisual').value)throw Error('Select reviewed media for this character.');const generation=runs.find(x=>x.id===voice.generationId);const split=id=>get(id).value.split(',').map(x=>x.trim()).filter(Boolean);const pronunciation=get('pronunciation').value.split('\n').filter(x=>x.trim()).map(x=>{const parts=x.split('=');if(parts.length!==2)throw Error('Use word=spoken form for pronunciation.');return {word:parts[0].trim(),speakAs:parts[1].trim()};});await call(base()+'/packages',{operationId:crypto.randomUUID(),key:get('packageKey').value,version:Number(get('packageVersion').value),rules:{profileRevisionId:character.profile.id,audienceId:get('audience').value,locale:get('locale').value,presentationStyle:get('packageStyle').value,visualAnchor:character.profile.rules.visualAnchor,voiceAnchor:character.profile.rules.voiceAnchor,palette:split('palette'),styleRules:get('styleRules').value.split('\n').map(x=>x.trim()).filter(Boolean),poses:split('poses'),sceneReferences:split('scenes'),pronunciation,visualVersionId:get('packageVisual').value,voiceVersionId:voice.id,additionalVersionIds:[],voiceProfileKey:generation?generation.snapshot.profile.key:'owned-recording.v1',voiceResourceKey:generation?generation.snapshot.profile.resourceKey:voice.id}});await load();}catch(e){get('status').textContent=e.message;}};
get('speechInventory').onclick=async()=>{try{get('speechResources').textContent=JSON.stringify(await call(base()+'/speech-adapters'),null,2);}catch(e){get('status').textContent=e.message;}};get('load').onclick=load;
get('upload').onclick=async()=>{try{const file=get('file').files[0];if(!file||file.size>1048576)throw Error('Choose a file up to1MiB.');const raw=new Uint8Array(await file.arrayBuffer());const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',raw))).map(x=>x.toString(16).padStart(2,'0')).join('').toUpperCase();let binary='';for(let p=0;p<raw.length;p+=8192)binary+=String.fromCharCode(...raw.subarray(p,p+8192));const same=versions.filter(x=>x.characterProfileRevisionId===get('character').value);await call(base()+'/assets',{operationId:crypto.randomUUID(),key:get('key').value,version:Number(get('version').value),fileName:file.name,accessibilityDescription:get('description').value,kind:get('kind').value,bytes:btoa(binary),expectedSha256:digest,license:{kind:get('license').value,evidenceReference:get('permission').value,sourceSnapshotIds:get('sources').value.split(',').map(x=>x.trim()).filter(Boolean),commercial:false,adaptation:true,attribution:get('attribution').value},audienceId:get('audience').value,locale:get('locale').value,characterProfileRevisionId:get('character').value||null,parentVersionIds:[]});await load();}catch(e){get('status').textContent=e.message;}};
get('submit').onclick=async()=>{try{const result=await call(base()+'/'+get('operation').value,JSON.parse(get('request').value));get('result').textContent=JSON.stringify(result,null,2);await load();}catch(e){get('status').textContent=e.message;}};
</script></html>
""";
}
